// Package config defines the waythrough.yaml schema: the language servers
// Waythrough starts and how to know when each one is ready.
package config

import (
	"fmt"
	"os"

	"go.yaml.in/yaml/v3"
)

// Readiness names how Waythrough decides a language server can answer a
// request, not merely that its process has started.
type Readiness string

const (
	// ReadinessProgress waits for every LSP workDoneProgress token the
	// server opens to close before treating the server as ready.
	ReadinessProgress Readiness = "progress"
	// ReadinessHandshake treats the server as ready as soon as the
	// initialize/initialized handshake completes. An explicit opt-in for
	// servers that do no background indexing.
	ReadinessHandshake Readiness = "handshake"
)

// LanguageServer is one entry in waythrough.yaml: how to start a language
// server and which files it handles.
type LanguageServer struct {
	Name                  string            `yaml:"name"`
	Command               string            `yaml:"command"`
	Args                  []string          `yaml:"args,omitempty"`
	Readiness             Readiness         `yaml:"readiness,omitempty"`
	Filetypes             map[string]string `yaml:"filetypes"`
	Env                   map[string]string `yaml:"env,omitempty"`
	InitializationOptions map[string]any    `yaml:"initialization_options,omitempty"`
}

// Config is the parsed content of waythrough.yaml.
type Config struct {
	LanguageServers []LanguageServer `yaml:"language_servers"`
}

// Load reads and parses the waythrough.yaml file at path.
func Load(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read %s: %w", path, err)
	}

	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}, fmt.Errorf("parse %s: %w", path, err)
	}

	return cfg, nil
}
package config

import (
	"errors"
	"fmt"
)

// Validate checks that every language-server entry in cfg has what
// Waythrough needs to start it and route files to it.
func Validate(cfg Config) error {
	var errs []error
	seenNames := make(map[string]bool, len(cfg.LanguageServers))
	owner := make(map[string]string) // filetype extension -> owning entry id

	for i, entry := range cfg.LanguageServers {
		id := entryID(entry, i)

		if entry.Name == "" {
			errs = append(errs, fmt.Errorf("%s: missing name", id))
		} else if seenNames[entry.Name] {
			errs = append(errs, fmt.Errorf("%s: duplicate name %q", id, entry.Name))
		}
		seenNames[entry.Name] = true
		if entry.Command == "" {
			errs = append(errs, fmt.Errorf("%s: missing command", id))
		}
		if len(entry.Filetypes) == 0 {
			errs = append(errs, fmt.Errorf("%s: missing filetypes", id))
		}
		if !validReadiness(entry.Readiness) {
			errs = append(errs, fmt.Errorf("%s: invalid readiness %q (want %q or %q)",
				id, entry.Readiness, ReadinessProgress, ReadinessHandshake))
		}

		for ext := range entry.Filetypes {
			if other, claimed := owner[ext]; claimed {
				errs = append(errs, fmt.Errorf(
					"%s: filetype %q is already claimed by %s", id, ext, other))
				continue
			}
			owner[ext] = id
		}
	}

	return errors.Join(errs...)
}

func entryID(entry LanguageServer, index int) string {
	if entry.Name != "" {
		return fmt.Sprintf("entry %q", entry.Name)
	}
	return fmt.Sprintf("entry #%d", index)
}

func validReadiness(r Readiness) bool {
	return r == "" || r == ReadinessProgress || r == ReadinessHandshake
}
package cli

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/spf13/cobra"

	"github.com/gustavofsantos/waythrough/internal/config"
	"github.com/gustavofsantos/waythrough/internal/editor"
	"github.com/gustavofsantos/waythrough/internal/lsp"
)

// shutdownGrace bounds how long serve waits, after the MCP session ends,
// for the configured language servers to exit on their own before it kills
// them and returns.
const shutdownGrace = 10 * time.Second

func newServeCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "serve",
		Short: "Start the Waythrough MCP server over stdio",
	}

	configPath := configFlag(cmd, "serve from")
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		return runServe(*configPath)
	}

	return cmd
}

func runServe(configPath string) error {
	cfg, err := config.Load(configPath)
	if err != nil {
		return err
	}
	if err := config.Validate(cfg); err != nil {
		return err
	}

	absConfigPath, err := filepath.Abs(configPath)
	if err != nil {
		return fmt.Errorf("resolve %s: %w", configPath, err)
	}
	root := filepath.Dir(absConfigPath)

	// The language-server subprocesses live for as long as serve runs, not
	// for as long as any one MCP session does: only Shutdown below ends
	// them, never the signal-aware context the MCP transport listens on.
	manager := lsp.NewManager(root, cfg.LanguageServers)
	if err := manager.Start(context.Background()); err != nil {
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	server := editor.New(manager, cfg)
	runErr := server.Run(ctx, &mcp.StdioTransport{})

	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownGrace)
	defer cancel()
	_ = manager.Shutdown(shutdownCtx)

	if runErr != nil {
		return fmt.Errorf("mcp session: %w", runErr)
	}
	return nil
}
// Package cli implements the waythrough command-line interface.
package cli

import (
	"fmt"
	"io"

	"github.com/spf13/cobra"
)

// Execute runs the waythrough CLI with args and returns the process exit
// code. It writes normal output to stdout and errors to stderr.
func Execute(args []string, stdout, stderr io.Writer) int {
	root := newRootCommand()
	root.SetArgs(args)
	root.SetOut(stdout)
	root.SetErr(stderr)
	root.SilenceUsage = true
	root.SilenceErrors = true

	if err := root.Execute(); err != nil {
		_, _ = fmt.Fprintln(stderr, err)
		return 1
	}
	return 0
}

// configFlag registers the --config flag shared by every subcommand that
// reads waythrough.yaml, and returns the value cobra will fill in.
func configFlag(cmd *cobra.Command, verb string) *string {
	usage := fmt.Sprintf("path to the config file to %s", verb)
	return cmd.Flags().String("config", "waythrough.yaml", usage)
}

func newRootCommand() *cobra.Command {
	root := &cobra.Command{
		Use:     "waythrough",
		Short:   "Waythrough manages configured LSP servers for coding agents",
		Version: version,
	}

	root.AddCommand(newInitCommand())
	root.AddCommand(newValidateCommand())
	root.AddCommand(newServeCommand())

	return root
}
package config_test

import (
	"os"
	"path/filepath"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"github.com/gustavofsantos/waythrough/internal/config"
)

func writeFile(path, content string) {
	Expect(os.WriteFile(path, []byte(content), 0o644)).To(Succeed())
}

var _ = Describe("Load", func() {
	var path string

	BeforeEach(func() {
		path = filepath.Join(GinkgoT().TempDir(), "waythrough.yaml")
	})

	When("the file holds a well-formed language-server entry", func() {
		BeforeEach(func() {
			writeFile(path, `
language_servers:
  - name: clojure-lsp
    command: clojure-lsp
    args: ["--verbose"]
    filetypes:
      .clj: clojure
`)
		})

		It("parses the entry's fields", func() {
			cfg, err := config.Load(path)
			Expect(err).NotTo(HaveOccurred())
			Expect(cfg.LanguageServers).To(HaveLen(1))

			entry := cfg.LanguageServers[0]
			Expect(entry.Name).To(Equal("clojure-lsp"))
			Expect(entry.Command).To(Equal("clojure-lsp"))
			Expect(entry.Args).To(Equal([]string{"--verbose"}))
			Expect(entry.Filetypes).To(Equal(map[string]string{".clj": "clojure"}))
		})
	})

	When("the file is not valid YAML", func() {
		BeforeEach(func() {
			writeFile(path, "language_servers: [\n")
		})

		It("returns a parse error", func() {
			_, err := config.Load(path)
			Expect(err).To(HaveOccurred())
		})
	})

	When("the file does not exist", func() {
		It("returns an error", func() {
			_, err := config.Load(filepath.Join(GinkgoT().TempDir(), "missing.yaml"))
			Expect(err).To(HaveOccurred())
		})
	})
})

var _ = Describe("Validate", func() {
	valid := func() config.Config {
		return config.Config{
			LanguageServers: []config.LanguageServer{
				{
					Name:      "clojure-lsp",
					Command:   "clojure-lsp",
					Filetypes: map[string]string{".clj": "clojure"},
				},
			},
		}
	}

	When("every entry has a name, a command, and at least one filetype mapping", func() {
		It("returns no error", func() {
			Expect(config.Validate(valid())).To(Succeed())
		})
	})

	When("an entry is missing its name", func() {
		It("names the missing field and identifies the entry by index", func() {
			cfg := valid()
			cfg.LanguageServers[0].Name = ""

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("missing name"))
			// The entry's own name is what's missing, so unlike every other
			// validation error here, it must identify the entry by index.
			Expect(err.Error()).To(ContainSubstring("entry #0"))
		})
	})

	When("two entries share the same name", func() {
		It("names the duplicate", func() {
			cfg := valid()
			cfg.LanguageServers = append(cfg.LanguageServers, config.LanguageServer{
				Name:      "clojure-lsp",
				Command:   "clojure-lsp-alt",
				Filetypes: map[string]string{".cljc": "clojure"},
			})

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("clojure-lsp"))
			Expect(err.Error()).To(ContainSubstring("duplicate"))
		})
	})

	When("two entries claim the same filetype", func() {
		It("names the extension and both entries", func() {
			cfg := valid()
			cfg.LanguageServers = append(cfg.LanguageServers, config.LanguageServer{
				Name:      "clojure-lsp-alt",
				Command:   "clojure-lsp-alt",
				Filetypes: map[string]string{".clj": "clojure"},
			})

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring(".clj"))
			Expect(err.Error()).To(ContainSubstring("clojure-lsp"))
			Expect(err.Error()).To(ContainSubstring("clojure-lsp-alt"))
		})
	})

	When("an entry is missing its command", func() {
		It("names the missing field and the entry", func() {
			cfg := valid()
			cfg.LanguageServers[0].Command = ""

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("command"))
			Expect(err.Error()).To(ContainSubstring("clojure-lsp"))
		})
	})

	When("an entry is missing its filetypes", func() {
		It("names the missing field and the entry", func() {
			cfg := valid()
			cfg.LanguageServers[0].Filetypes = nil

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("filetypes"))
			Expect(err.Error()).To(ContainSubstring("clojure-lsp"))
		})
	})

	When("an entry sets an unknown readiness value", func() {
		It("names the invalid value", func() {
			cfg := valid()
			cfg.LanguageServers[0].Readiness = "eager"

			err := config.Validate(cfg)
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("eager"))
		})
	})

	DescribeTable("accepts every valid readiness value, including unset",
		func(readiness config.Readiness) {
			cfg := valid()
			cfg.LanguageServers[0].Readiness = readiness
			Expect(config.Validate(cfg)).To(Succeed())
		},
		Entry("unset", config.Readiness("")),
		Entry("progress", config.ReadinessProgress),
		Entry("handshake", config.ReadinessHandshake),
	)
})
package cli_test

import (
	"bytes"
	"os"
	"path/filepath"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"go.yaml.in/yaml/v3"

	"github.com/gustavofsantos/waythrough/internal/cli"
	"github.com/gustavofsantos/waythrough/internal/config"
)

func writeConfigFile(path, content string) {
	Expect(os.WriteFile(path, []byte(content), 0o644)).To(Succeed())
}

// twoServersOneExtension breaks the one-server-per-extension rule, the
// invariant every command that reads a config must refuse to run against.
// The two entry names are deliberately not prefixes of one another, so an
// assertion naming one cannot pass on the other.
const twoServersOneExtension = `
language_servers:
  - name: clojure-lsp
    command: clojure-lsp
    filetypes:
      .clj: clojure
  - name: clj-kondo-lsp
    command: clj-kondo-lsp
    filetypes:
      .clj: clojure
`

var _ = Describe("waythrough CLI", func() {
	var (
		configPath string
		stdout     *bytes.Buffer
		stderr     *bytes.Buffer
	)

	BeforeEach(func() {
		configPath = filepath.Join(GinkgoT().TempDir(), "waythrough.yaml")
		stdout = &bytes.Buffer{}
		stderr = &bytes.Buffer{}
	})

	run := func(args ...string) int {
		return cli.Execute(args, stdout, stderr)
	}

	Describe("init", func() {
		When("no config file exists at the target path", func() {
			It("creates a config file with one example language server", func() {
				code := run("init", "--config", configPath)
				Expect(code).To(Equal(0))

				data, err := os.ReadFile(configPath)
				Expect(err).NotTo(HaveOccurred())

				var cfg config.Config
				Expect(yaml.Unmarshal(data, &cfg)).To(Succeed())
				Expect(cfg.LanguageServers).To(HaveLen(1))
			})
		})

		When("a config file already exists at the target path", func() {
			BeforeEach(func() {
				writeConfigFile(configPath, "language_servers: []\n")
			})

			It("refuses to overwrite the file and exits non-zero", func() {
				code := run("init", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).To(ContainSubstring(configPath))

				data, err := os.ReadFile(configPath)
				Expect(err).NotTo(HaveOccurred())
				Expect(string(data)).To(Equal("language_servers: []\n"))
			})
		})
	})

	Describe("validate", func() {
		When("every entry has a name, a command, and a filetype mapping", func() {
			BeforeEach(func() {
				writeConfigFile(configPath, `
language_servers:
  - name: clojure-lsp
    command: clojure-lsp
    filetypes:
      .clj: clojure
`)
			})

			It("exits zero", func() {
				Expect(run("validate", "--config", configPath)).To(Equal(0))
			})
		})

		When("an entry is missing its command", func() {
			BeforeEach(func() {
				writeConfigFile(configPath, `
language_servers:
  - name: clojure-lsp
    filetypes:
      .clj: clojure
`)
			})

			It("exits non-zero and names the missing field and the entry", func() {
				code := run("validate", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).To(ContainSubstring("command"))
				Expect(stderr.String()).To(ContainSubstring("clojure-lsp"))
			})
		})

		When("an entry sets an unknown readiness value", func() {
			BeforeEach(func() {
				writeConfigFile(configPath, `
language_servers:
  - name: clojure-lsp
    command: clojure-lsp
    readiness: eager
    filetypes:
      .clj: clojure
`)
			})

			It("exits non-zero and names the invalid value", func() {
				code := run("validate", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).To(ContainSubstring("eager"))
			})
		})

		When("the file is not valid YAML", func() {
			BeforeEach(func() {
				writeConfigFile(configPath, "language_servers: [\n")
			})

			It("exits non-zero and reports a parse error", func() {
				code := run("validate", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).NotTo(BeEmpty())
			})
		})

		When("two entries claim the same file extension", func() {
			BeforeEach(func() { writeConfigFile(configPath, twoServersOneExtension) })

			It("exits non-zero and names the extension and both entries", func() {
				code := run("validate", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).To(ContainSubstring("already claimed"))
				Expect(stderr.String()).To(ContainSubstring(".clj"))
				Expect(stderr.String()).To(ContainSubstring("clojure-lsp"))
				Expect(stderr.String()).To(ContainSubstring("clj-kondo-lsp"))
			})
		})
	})

	// serve is covered here only for configs it must reject. A config it
	// accepts sends serve into mcp.Server.Run on a stdio transport, which
	// reads the test binary's own stdin. What that returns depends on how
	// the suite was started, so there is nothing stable to assert on.
	Describe("serve", func() {
		When("two entries claim the same file extension", func() {
			BeforeEach(func() { writeConfigFile(configPath, twoServersOneExtension) })

			// One extension routes to exactly one language server. Waythrough
			// resolves a file to a server by its extension alone, so a second
			// claim on .clj leaves the routing table to pick a winner in
			// silence, and an agent gets definitions from whichever entry came
			// last. serve must refuse before it spawns a single subprocess.
			It("refuses to start, and names the extension and both entries", func() {
				code := run("serve", "--config", configPath)
				Expect(code).NotTo(Equal(0))
				Expect(stderr.String()).To(ContainSubstring("already claimed"))
				Expect(stderr.String()).To(ContainSubstring(".clj"))
				Expect(stderr.String()).To(ContainSubstring("clojure-lsp"))
				Expect(stderr.String()).To(ContainSubstring("clj-kondo-lsp"))
			})
		})
	})
})
# Waythrough

A coding agent without a language server guesses at your code. It reads
text and looks for matching names. It does not know a symbol's
definition, and it does not know every place that uses it.

Waythrough closes that gap. Waythrough is a Model Context Protocol
(MCP) server. It starts and manages Language Server Protocol (LSP)
servers. It offers their features to the agent as MCP tools.

Point a coding agent at Waythrough. Claude Code, Codex, and
Antigravity are coding agents. Waythrough gives the agent the same
"go to definition" and "find references" power as a modern editor.

## Status

This project is in early setup. It has six MCP tools. Tests run
them against a test language server, not against a real one yet.

## Install

Waythrough publishes binaries for Linux and macOS. This project is
also its own Homebrew tap. Run these commands to install it:

```sh
brew tap gustavofsantos/waythrough https://github.com/gustavofsantos/waythrough
brew install waythrough
```

## Quick start

1. Create a `waythrough.yaml` file in your project root. Each entry
   names a language server, the command that starts it, and the file
   extensions it handles:

   ```yaml
   language_servers:
     - name: gopls
       command: gopls
       args: []
       filetypes:
         .go: go
   ```

   Run `waythrough init` to write a starter config for Clojure
   instead. Edit it for your own language servers. Then run
   `waythrough validate` to check the file for errors.

2. Add Waythrough as an MCP server in your coding agent's config.
   Pass an absolute path to `--config`, so Waythrough finds
   `waythrough.yaml` no matter where the agent starts it from. The
   agent starts Waythrough over stdio:

   ```json
   {
     "mcpServers": {
       "waythrough": {
         "command": "waythrough",
         "args": ["serve", "--config", "/absolute/path/to/waythrough.yaml"]
       }
     }
   }
   ```

3. Ask your coding agent to find a definition or list references. The
   agent calls Waythrough's MCP tools. Waythrough forwards the
   request to the language server for that file type.

## Tools

Waythrough exposes these MCP tools to a connected coding agent:

- `get_definition` — find where a symbol's definition is, given a
  file position.
- `list_references` — find every place that uses a symbol, given a
  file position.
- `rename_symbol` — build the list of edits that rename a symbol,
  across every file it touches. It does not write the edits to disk.
  Your agent applies them.
- `signature_help` — list the signatures a call could match, given a
  file position inside that call. It also says which signature and
  which parameter the position is on.
- `get_diagnostics` — list the problems a language server finds in a
  file. The language server must advertise pull diagnostics at its
  handshake. One that does not fails the call with an error naming it,
  rather than reporting a clean file. `gopls` pushes its diagnostics
  by default and advertises no pull support, so it fails this call
  today.
- `restart_server` — restart one language server by name. The call
  returns only when the replacement can answer, so the next call
  does not reach a server that is still starting. Every other
  language server keeps running. Use it when a server's answers no
  longer match the code on disk. Waythrough cannot see that a
  server answers from a stale index, so your agent must decide.

