	out := diagnosticsOutput{Diagnostics: make([]diagnostic, len(diagnostics))}
	for i, d := range diagnostics {
		out.Diagnostics[i] = diagnostic{
			StartLine:   d.StartLine,
			StartColumn: d.StartColumn,
			EndLine:     d.EndLine,
			EndColumn:   d.EndColumn,
			Severity:    d.Severity,
			Message:     d.Message,
			Source:      d.Source,
			Code:        d.Code,
		}
	}
	return out
}

