	data, err := os.ReadFile(path)
	Expect(err).NotTo(HaveOccurred())

	var lines []string
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if line == "" {
			continue
		}
		lines = append(lines, line)
	}
	return lines
}

