// Package config defines the waythrough.yaml schema: the language servers
// Waythrough starts and how to know when each one is ready.
package config

import (
	"fmt"
	"os"

	"go.yaml.in/yaml/v3"
)

// Readiness names how Waythrough decides a language server can answer a
// request, not merely that its process has started.
type Readiness string

const (
	// ReadinessProgress waits for every LSP workDoneProgress token the
	// server opens to close before treating the server as ready.
	ReadinessProgress Readiness = "progress"
	// ReadinessHandshake treats the server as ready as soon as the
	// initialize/initialized handshake completes. An explicit opt-in for
	// servers that do no background indexing.
	ReadinessHandshake Readiness = "handshake"
)

// LanguageServer is one entry in waythrough.yaml: how to start a language
// server and which files it handles.
type LanguageServer struct {
	Name                  string            `yaml:"name"`
	Command               string            `yaml:"command"`
	Args                  []string          `yaml:"args,omitempty"`
	Readiness             Readiness         `yaml:"readiness,omitempty"`
	Filetypes             map[string]string `yaml:"filetypes"`
	Env                   map[string]string `yaml:"env,omitempty"`
	InitializationOptions map[string]any    `yaml:"initialization_options,omitempty"`
}

// Config is the parsed content of waythrough.yaml.
type Config struct {
	LanguageServers []LanguageServer `yaml:"language_servers"`
}

// Load reads and parses the waythrough.yaml file at path.
func Load(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read %s: %w", path, err)
	}

	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}, fmt.Errorf("parse %s: %w", path, err)
	}

	return cfg, nil
}
package config

import (
	"errors"
	"fmt"
)

// Validate checks that every language-server entry in cfg has what
// Waythrough needs to start it and route files to it.
func Validate(cfg Config) error {
	var errs []error
	seenNames := make(map[string]bool, len(cfg.LanguageServers))
	owner := make(map[string]string) // filetype extension -> owning entry id

	for i, entry := range cfg.LanguageServers {
		id := entryID(entry, i)

		if entry.Name == "" {
			errs = append(errs, fmt.Errorf("%s: missing name", id))
		} else if seenNames[entry.Name] {
			errs = append(errs, fmt.Errorf("%s: duplicate name %q", id, entry.Name))
		}
		seenNames[entry.Name] = true
		if entry.Command == "" {
			errs = append(errs, fmt.Errorf("%s: missing command", id))
		}
		if len(entry.Filetypes) == 0 {
			errs = append(errs, fmt.Errorf("%s: missing filetypes", id))
		}
		if !validReadiness(entry.Readiness) {
			errs = append(errs, fmt.Errorf("%s: invalid readiness %q (want %q or %q)",
				id, entry.Readiness, ReadinessProgress, ReadinessHandshake))
		}

		for ext := range entry.Filetypes {
			if other, claimed := owner[ext]; claimed {
				errs = append(errs, fmt.Errorf(
					"%s: filetype %q is already claimed by %s", id, ext, other))
				continue
			}
			owner[ext] = id
		}
	}

	return errors.Join(errs...)
}

func entryID(entry LanguageServer, index int) string {
	if entry.Name != "" {
		return fmt.Sprintf("entry %q", entry.Name)
	}
	return fmt.Sprintf("entry #%d", index)
}

func validReadiness(r Readiness) bool {
	return r == "" || r == ReadinessProgress || r == ReadinessHandshake
}

